command:
let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.getFlag("vagabond-app", "deadeye"))?.actor;
}

if (!hero || !hero.getFlag("vagabond-app", "deadeye")) return;

const name = hero.system.parent.name;
const deadeye1 = hero.effects.find(fx => fx.name.toUpperCase() === "DEADEYE 1");
const deadeye2 = hero.effects.find(fx => fx.name.toUpperCase() === "DEADEYE 2");
const deadeye3 = hero.effects.find(fx => fx.name.toUpperCase() === "DEADEYE 3");

let makeDeadeye1, makeDeadeye2, makeDeadeye3;

if (event.ctrlKey || event.shiftKey || deadeye3) {
  token.actor.deleteEmbeddedDocuments("ActiveEffect", [
    ...(deadeye1 ? [deadeye1.id] : []),
    ...(deadeye2 ? [deadeye2.id] : []),
    ...(deadeye3 ? [deadeye3.id] : [])]);
} else if (deadeye2) {
  makeDeadeye3 = true;
} else if (deadeye1) {
  makeDeadeye2 = true;
} else {
  makeDeadeye1 = true;
}

async function makeDeadeye(deadeyeNumber) {
    const effectData = {
    name: `Deadeye ${deadeyeNumber}`,
    img: "icons/magic/perception/eye-ringed-glow-angry-large-teal.webp",
    showIcon: 2,
    changes: [
      {
        key: "system.modifiers.skillCheck.ranged.critThreshold",
        type: "add",
        mode: 2,
        value: 1,
        priority: 20
      }
    ]
  }

  await token.actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
};

if (makeDeadeye1) {
  await makeDeadeye(1);
}

if (makeDeadeye2) {
  await makeDeadeye(2);
}

if (makeDeadeye3) {
  await makeDeadeye(3);
}
